<?php
namespace Tests\Feature;use App\Models\Company;use App\Models\Job;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class CommercialApiTest extends TestCase{use RefreshDatabase;public function test_company_creates_scoped_key_and_reads_jobs():void{$owner=User::factory()->create(['account_type'=>'company']);$company=Company::create(['name'=>'Acme','slug'=>'acme','status'=>'active','country_code'=>'DO']);$company->members()->attach($owner->id,['role'=>'owner','status'=>'active']);Job::create(['company_id'=>$company->id,'slug'=>'job','title'=>'Developer','summary'=>'Job','location'=>'Santiago','modality'=>'Remoto','contract_type'=>'Tiempo completo','status'=>'active']);$key=$this->actingAs($owner,'sanctum')->postJson('/api/v1/company/api-clients',['name'=>'ERP','scopes'=>['jobs:read']])->assertCreated()->json('data.key');$this->withToken($key)->getJson('/api/v1/commercial/jobs')->assertOk()->assertJsonCount(1,'data.data');$this->withToken($key)->getJson('/api/v1/commercial/applications')->assertForbidden();}public function test_multicountry_configuration_and_predictive_endpoint():void{$owner=User::factory()->create(['account_type'=>'company']);$company=Company::create(['name'=>'Acme','slug'=>'acme','status'=>'active']);$company->members()->attach($owner->id,['role'=>'owner','status'=>'active']);$this->actingAs($owner,'sanctum')->putJson('/api/v1/company/country',['country_code'=>'US'])->assertOk()->assertJsonPath('data.country_code','US');$this->actingAs($owner,'sanctum')->getJson('/api/v1/company/analytics/predictive')->assertOk()->assertJsonPath('data.confidence','baja');}}
